<!-- 模块职责：当前身份可访问的订单和客户只读查询。 -->
<script setup>
import Icon from '../components/Icon.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { dateTime } from '../format'
const props = defineProps({ store: Object })
const store = props.store, s = store.state
</script>
<template><section class="card search-card"><div><h2>查询业务记录</h2><p>直接读取当前身份有权访问的订单或客户资料。</p></div><form class="inline-form" @submit.prevent="store.lookup"><select v-model="s.lookupKind" aria-label="数据类型" :disabled="s.busy" @change="s.lookupResult = null; s.lookupId = s.lookupKind === 'orders' ? 'BF2026001' : 'CUST-DEMO-001'"><option value="orders">订单</option><option value="customers">客户</option></select><input v-model="s.lookupId" aria-label="业务编号" :disabled="s.busy" placeholder="输入业务编号" /><button class="button primary" :disabled="s.busy || !s.lookupId.trim()">查询记录</button></form></section><section v-if="!s.lookupResult" class="card empty-state tall-empty"><span class="empty-icon"><Icon name="database" :size="30" /></span><h3>从业务事实出发</h3><p>可以查询 BF2026001、BF2026002、BF2026003 三类虚构订单。<br />员工的客户范围为 CUST-DEMO-001。</p></section><section v-else class="card data-card"><div class="card-header"><h2>{{ s.lookupResult.order_id ? '订单详情' : '客户详情' }}</h2><span class="chip">只读数据</span></div><div class="card-body"><dl v-if="s.lookupResult.order_id" class="detail-list"><dt>订单编号</dt><dd class="mono">{{ s.lookupResult.order_id }}</dd><dt>客户编号</dt><dd class="mono">{{ s.lookupResult.customer_id }}</dd><dt>订单状态</dt><dd><StatusBadge :status="s.lookupResult.status" :text="s.lookupResult.status === 'pending' ? '待处理' : undefined" /></dd><dt>创建时间</dt><dd>{{ dateTime(s.lookupResult.created_at) }}</dd><dt>承诺发货</dt><dd>{{ dateTime(s.lookupResult.promised_ship_at) }}</dd><dt>实际发货</dt><dd>{{ s.lookupResult.shipped_at ? dateTime(s.lookupResult.shipped_at) : '尚未发货' }}</dd></dl><dl v-else class="detail-list"><dt>客户编号</dt><dd class="mono">{{ s.lookupResult.customer_id }}</dd><dt>客户名称</dt><dd>{{ s.lookupResult.name }}</dd><dt>演示联系方式</dt><dd>{{ s.lookupResult.contact }}</dd></dl><p class="footnote">此页面只展示查询事实。售后建议需要政策依据和业务判断；不能只依据 pending 状态判定超期。</p></div></section></template>
